import React from 'react';
import Seo from '../components/Seo';
import Icon from '../components/Icon';
export default function Contact(){return <><Seo title="Contact" path="/contact" description="Contacter Huriel Nguimbi via Beyond31 pour échanger autour d’un projet, d’une collaboration ou d’une idée."/><section className="contact-page elegant-contact"><p className="eyebrow"><span/>Contact</p><h1>On peut simplement<br/><em>en parler.</em></h1><p>Projet, collaboration, retour ou curiosité : le plus direct reste un message.</p><div className="contact-glass"><a href="mailto:contact@beyond31.online"><Icon name="contact"/><span><small>Email</small><strong>contact@beyond31.online</strong></span><Icon name="arrow"/></a><a href="tel:+33625139627"><Icon name="phone"/><span><small>Téléphone</small><strong>+33 6 25 13 96 27</strong></span><Icon name="arrow"/></a><a href="https://instagram.com/beyond_31_" target="_blank" rel="noopener noreferrer"><Icon name="spark"/><span><small>Instagram</small><strong>@beyond_31_</strong></span><Icon name="arrow"/></a></div></section></>}
